INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65135780', 65135780, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Sosialisasi Ketenagakerjaan di Media', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 3076642000, 'February 2026', 'APBN - RUPIAH MURNI (A), APBN - PNBP (D)', 1, 1, '25 Paket', 'Paket kegiatan Sosialisasi Ketenagakerjaan di Media merupakan pekerjaan jasa komunikasi publik yang bertujuan untuk mendiseminasikan kebijakan, program, dan informasi strategis Kementerian Ketenagakerjaan kepada masyarakat luas melalui pemanfaatan media massa dan media digital. Ruang lingkup pekerjaan meliputi perencanaan, pelaksanaan, serta pelaporan kegiatan sosialisasi ketenagakerjaan melalui penayangan informasi di media, baik dalam bentuk siaran pers, advertorial, maupun berita, serta produksi konten kreatif yang relevan dengan isu ketenagakerjaan untuk ditayangkan pada media yang memiliki jangkauan audiens nasional maupun segmentasi tertentu. Pekerjaan ini diharapkan mampu meningkatkan pemahaman publik, membentuk persepsi positif, serta memperkuat citra dan reputasi Kementerian Ketenagakerjaan melalui penyampaian informasi yang akurat, mudah dipahami, dan sesuai dengan kaidah jurnalistik serta etika komunikasi publik pemerintah.', 'Spesifikasi pekerjaan dalam paket ini mencakup beberapa komponen utama antara lain: Pertama, penyusunan dan penayangan siaran pers/advertorial/berita di media. Penyedia wajib melaksanakan penayangan informasi ketenagakerjaan di media massa atau media daring sesuai dengan materi yang disiapkan oleh Kementerian Ketenagakerjaan atau hasil pengolahan bersama. Penayangan dilakukan dengan memperhatikan akurasi substansi, kepatuhan terhadap kaidah jurnalistik, serta kesesuaian dengan karakter dan segmentasi media yang dituju. Kedua, penayangan siaran pers di media. Penyedia bertanggung jawab melakukan distribusi dan penayangan siaran pers resmi Kementerian Ketenagakerjaan ke media yang relevan, memastikan keterbacaan, visibilitas, dan jangkauan audiens sesuai target sosialisasi yang ditetapkan. Setiap penayangan harus dapat dibuktikan dengan dokumentasi dan laporan pemuatan. Ketiga, produksi konten kreatif. Penyedia melaksanakan produksi konten komunikasi berupa teks, visual, grafis, infografik, foto, atau video singkat yang memuat pesan ketenagakerjaan. Konten diproduksi dengan pendekatan kreatif namun tetap informatif, sesuai identitas dan pedoman komunikasi Kementerian Ketenagakerjaan, serta layak ditayangkan di media massa dan/atau media digital. Keempat, penayangan konten kreatif di media. Konten yang telah diproduksi ditayangkan pada media yang telah disepakati dengan memperhatikan waktu tayang, format publikasi, dan kesesuaian dengan kebijakan redaksional media. Penayangan ditujukan untuk mendukung efektivitas sosialisasi dan memperluas jangkauan pesan kepada publik sasaran. Kelima, pelaporan pelaksanaan pekerjaan. Penyedia wajib menyampaikan laporan pelaksanaan kegiatan secara berkala dan/atau akhir, yang memuat daftar media, jenis publikasi, waktu penayangan, tautan atau bukti pemuatan, serta ringkasan capaian kegiatan sosialisasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1936702);
