INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65072694', 65072694, 'analyze_legacy', 'Kementerian Sosial', 'central', 'PUSAT PENDIDIKAN PELATIHAN DAN PENGEMBANGAN PROFESI', 'Pengadaan Barang Perlengkapan Pengasramaan Siswa pada Sekolah Rakyat 1C Terintegrasi 47 Kota Samarinda Wilayah 12', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Samarinda (Kota)', 205375000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Menyediakan Paket Perlengkapan Pengasramaan pada Sekolah Rakyat 1C Terintegrasi 47 Kota Samarinda Wilayah 12 antara lain : 1. Perlengkapan Kamar Siswa berupa Bantal, Guling, Handuk, Selimut dan Sprei Single Katun 2. Perlengkapan Siswa berupa Pakaian Dalam, Pakaian Santai, Keperluan Kebersihan Diri, Keperluan Wanita dan Jilbab Santai 3. Perlengkapan Pendukung Pembinaan berupa Peralatan Ibadah untuk siswa', 'Menyediakan Paket Perlengkapan Pengasramaan pada Sekolah Rakyat 1C Terintegrasi 47 Kota Samarinda Wilayah 12 antara lain : 1. Perlengkapan Kamar Siswa • Bantal [25 Org x 2 BH x 1 rom] • Guling [25 Org x 2 BH x 1 rom] • Handuk [25 Org x 2 BH x 1 rom] • Selimut [25 Org x 2 BH x 1 rom] • Sprei Single Katun [25 Org x 2 BH x 1 rom] 2. Perlengkapan Siswa • Pakaian Dalam [25 Org x 7 SET x 1 rom] • Pakaian Santai [25 Org x 7 SET x 1 rom] • Keperluan Kebersihan Diri [25 Org x 1 SET x 1 rom x 12 BLN] • Keperluan Wanita [15 Org x 1 SET x 1 rom x 12 BLN] • Jilbab Santai [15 Org x 7 BH x 1 rom] 3. Perlengkapan Pendukung Pembinaan • Peralatan Ibadah [25 Org x 1 SET x 1 rom]', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1939074);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65115386', 65115386, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT WAKIL PRESIDEN', 'Jasa Konsultansi Tenaga Ahli Advokasi dan Kebijakan Publik (TA-AKP) TP2S Tahun 2026', 'Jasa Konsultansi', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 5432631000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 paket', '1) Identifikasi dan pemantauan pelaksanaan kebijakan terkait dgn pelaksanaan P3S di pusat dan daerah. 2) Pembaharuan strategi advokasi termasuk instrumen, analisis kebijakan, dan peningkatan kapasitas dan tata kelola berbagai program/kegiatan P3S. 3) Menganalisis, debottlenecking, dan merekomendasikan kebijakan terkait pelaksanaan P3S. 4) Menghasilkan laporan tertulis,paparan atau bahan publikasi lainnya yg diproduksi secara periodik utk P3S. 5) Menyediakan bahan komunikasi dan advokasi yg efektif dgn berbagai unsur terkait. 6) Melakukan koordinasi teknis dgn K/L yg terkait dlm pelaksanaan kegiatan advokasi program P3S. 7) Menyiapkan materi pendukung rapat koordinasi nasional dan rapat koordinasi teknis percepatan penurunan stunting. 8) Menjaga profesionalitas, integritas, loyalitas, dan kesetiaan kpd pemberi kerja. 9) Melaksanakan tugas yg diberikan oleh Setwapres dan Team Leader dgn penuh tanggungjawab.', '1) Mempunyai pendidikan minimal S1 pada bidang Studi Pembangunan/Kebijakan Publik/Administrasi Publik, atau bidang lain yang relevan. 2) Mempunyai pengalaman kerja minimal 7 tahun untuk S1 atau S2 dengan pengalaman 5 tahun dalam bidang kebijakan publik/advokasi/tata kelola pemerintahan/pemberdayaan masyarakat/peningkatan kapasitas atau bidang lain yang relevan. 3) Mempunyai pengalaman bekerja sama dengan lembaga pemerintah di pusat, daerah, dan lembaga serta mitra non pemerintah. 4) Mempunyai keterampilan teknis dan pengalaman dalam menyusun kertas kerja kebijakan (policy paper), analisis kebijakan, perencanaan program/kegiatan, penyelesaian pelaporan, dan kerangka pemantauan dan evaluasi. 5) Mempunyai kemampuan advokasi, membangun kapasitas dan kolaborasi kerja, serta memiliki jejaring kerja yang luas pada Kementerian/Lembaga, pemerintah daerah, LSM, swasta, mitra pembangunan, dan pemangku kepentingan terkait lainnya. 6) Mempunyai pengalaman kerja dalam isu kesehatan dan isu lintas bidang akan diprioritaskan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1939075);
